SELECT CAST(ORD_CLOSED_DT AS STRING) AS dia, CASE WHEN ITE_ITEM_FULL_UNIT_PRICE<200 THEN '1_<200' WHEN ITE_ITEM_FULL_UNIT_PRICE<500 THEN '2_200-500' WHEN ITE_ITEM_FULL_UNIT_PRICE<1500 THEN '3_500-1500' WHEN ITE_ITEM_FULL_UNIT_PRICE<3000 THEN '4_1500-3000' ELSE '5_>3000' END AS faixa, CASE WHEN PAYMENT_METHOD_1='pix' AND DXB_PAYMENT_METHOD='PIX' THEN 'Pix incentivado' WHEN PAYMENT_METHOD_1='pix' THEN 'Pix organico' WHEN PAYMENT_METHOD_TYPE_1='credit_card' THEN 'Credito' WHEN PAYMENT_METHOD_TYPE_1='account_money' THEN 'Meli saldo' WHEN PAYMENT_METHOD_TYPE_1='digital_currency' THEN 'Mercado Credito' WHEN PAYMENT_METHOD_TYPE_1='ticket' THEN 'Boleto' WHEN PAYMENT_METHOD_TYPE_1='prepaid_card' THEN 'Pre-pago' WHEN PAYMENT_METHOD_TYPE_1 IS NULL THEN 'Sem info' ELSE 'Outros' END AS meio, ROUND(SUM(F_NMV_LC)/1e6,4) nmv_mi, COUNT(DISTINCT ORD_ORDER_ID) ped FROM `meli-bi-data.WHOWNER.DM_EFICIENCIA_MLB` WHERE VERTICAL='HOME ELECTRONICS' AND DOM_DOMAIN_AGG1='LARGE APPLIANCES' AND ITE_ITEM_FULL_UNIT_PRICE>0 AND ORD_CLOSED_DT IN ('2026-02-01','2026-02-02','2026-02-03','2026-03-02','2026-03-03','2026-03-04','2026-04-03','2026-04-04','2026-04-05','2026-05-04','2026-05-05','2026-05-06','2026-06-05','2026-06-06','2026-06-07','2026-07-06','2026-07-07','2026-07-08') GROUP BY 1,2,3